// Watch capability index — record JAH-GAI-SMARTWATCH-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"sensors": 10, "battery_days": 2, "price_usd": 400};
var value = (m.sensors*m.battery_days/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAI-SMARTWATCH-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAI-SMARTWATCH-000001|' + value.toFixed(2) + ' capability index');

